// server.js
const express = require('express');
const zlib = require('zlib');
const app = express();

// Generate a repeated CSS rule to produce ~80KB of raw CSS text
const rule = 'body.mopinion-modal-active{overflow:hidden!important}\n';
const repeatCount = 10000; // adjust to target ~80KB raw
const cssText = rule.repeat(repeatCount);

// Prepare gzipped JSON payload
const jsonPayload = JSON.stringify(cssText);
const gzippedPayload = zlib.gzipSync(jsonPayload);

// Endpoint serving compressed JSON
app.get('/css-config.json', (req, res) => {
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Content-Encoding', 'gzip');
  res.send(gzippedPayload);
});

// Serve static HTML and client script
app.use(express.static('public'));

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Test server running: http://localhost:${PORT}`);
});


// public/index.html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Gzip-injected CSS Test</title>
</head>
<body>
  <h1>Gzip CSS injection demo</h1>
  <div class="mopinion-modal-active">Demo content</div>
  <script src="script.js"></script>
</body>
</html>


// public/script.js
// Fetch gzipped JSON, parse, then inject CSS into a style tag
fetch('/css-config.json')
  .then(response => response.text())
  .then(text => {
    const css = JSON.parse(text);
    const styleEl = document.createElement('style');
    styleEl.textContent = css;
    document.head.appendChild(styleEl);
  })
  .catch(err => console.error('Failed to load CSS config', err));


